shell_commands.command:
cd /testbed && patch -p1 <<'PATCH'
--- a/test/xchar-test.cc
+++ b/test/xchar-test.cc
@@ -440,6 +440,34 @@ TEST(locale_test, localized_double) {
   EXPECT_EQ(fmt::format(loc, "{:8L}", 1230.0), "   1~230");
 }

+TEST(locale_test, localized_double_alignment) {
+  auto loc = std::locale(std::locale(), new numpunct<char>());
+  EXPECT_EQ("              0?295", fmt::format(loc, "{:19.3Lf}", 0.295));
+  EXPECT_EQ("             -0?295", fmt::format(loc, "{:19.3Lf}", -0.295));
+  EXPECT_EQ("              1?295", fmt::format(loc, "{:19.3Lf}", 1.295));
+  EXPECT_EQ("             12?345", fmt::format(loc, "{:19.3Lf}", 12.345));
+  EXPECT_EQ("          2~194?139", fmt::format(loc, "{:19.3Lf}", 2194.139));
+  EXPECT_EQ("         12~345?678", fmt::format(loc, "{:19.3Lf}", 12345.678));
+  EXPECT_EQ("0?295     ", fmt::format(loc, "{:<10.3Lf}", 0.295));
+  EXPECT_EQ("**0?295***", fmt::format(loc, "{:*^10.3Lf}", 0.295));
+  EXPECT_EQ("000000?295", fmt::format(loc, "{:010.3Lf}", 0.295));
+  EXPECT_EQ("  1?234567", fmt::format(loc, "{:10.6Lf}", 1.234567));
+  EXPECT_EQ("     0?295", fmt::format(loc, "{:10Lg}", 0.295));
+  EXPECT_EQ("     0?295", fmt::format(loc, "{:10.3Lf}", 0.295f));
+  EXPECT_EQ("     0?295", fmt::format(loc, "{:10.3Lf}", 0.295L));
+}
+
+TEST(locale_test, localized_wdouble_alignment) {
+  auto loc = std::locale(std::locale(), new numpunct<wchar_t>());
+  EXPECT_EQ(L"              0?295", fmt::format(loc, L"{:19.3Lf}", 0.295));
+  EXPECT_EQ(L"             -0?295", fmt::format(loc, L"{:19.3Lf}", -0.295));
+  EXPECT_EQ(L"          2~194?139", fmt::format(loc, L"{:19.3Lf}", 2194.139));
+  EXPECT_EQ(L"0?295     ", fmt::format(loc, L"{:<10.3Lf}", 0.295));
+  EXPECT_EQ(L"**0?295***", fmt::format(loc, L"{:*^10.3Lf}", 0.295));
+}
+
 TEST(locale_test, format) {
   auto loc = std::locale(std::locale(), new numpunct<char>());
   EXPECT_EQ("1234567", fmt::format(std::locale(), "{:L}", 1234567));
PATCH
cmake -B build -S . && cmake --build build --parallel 4 --target xchar-test && build/bin/xchar-test --gtest_filter='locale_test.localized*alignment'

